// path from the root to target; true if found
bool Path(TreeNode node, TreeNode target, List<TreeNode> path) {
    if (node == null) return false;
    path.Add(node);
    if (node == target || Path(node.left, target, path) || Path(node.right, target, path))
        return true;
    path.RemoveAt(path.Count - 1);   // target is not under this node — drop it
    return false;
}
// the LCA is the last common node of the two paths

